class SystemInitializer {
    private static String databaseUrl;

    // Static initialization block
    static {
        System.out.println("[STEP 1] Static block executing: Initializing Database Connection Pool...");
        databaseUrl = "jdbc:postgresql://cloud-db.internal:5432/production";
    }

    public SystemInitializer(String clientName) {
        System.out.println("[STEP 2] Constructor executing for client: " + clientName);
    }

    public static String getDatabaseUrl() {
        return databaseUrl;
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("--- Main method started ---");

        // First instance:
        SystemInitializer s1 = new SystemInitializer("WebPortal");

        // Second instance:
        SystemInitializer s2 = new SystemInitializer("MobileApp");

        System.out.println("Shared DB: " + SystemInitializer.getDatabaseUrl());
    }
}

