class CountryCodeRegistry {
    private static String[] codeLookup = new String[26];

    // Populate static array via static block
    static {
        for (int i = 0; i < 26; i++) {
            codeLookup[i] = "ZONE-" + (char) ('A' + i);
        }
        System.out.println("CountryCodeRegistry initialized with 26 zones.");
    }

    public static String getZone(char letter) {
        char upper = Character.toUpperCase(letter);
        if (upper >= 'A' && upper <= 'Z') {
            return codeLookup[upper - 'A'];
        }
        return "ZONE-UNKNOWN";
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("Zone for 'A': " + CountryCodeRegistry.getZone('A'));
        System.out.println("Zone for 'M': " + CountryCodeRegistry.getZone('M'));
    }
}

