class FactorialLookup {
    private static int[] factorials = new int[6];

    static {
        factorials[0] = 1;
        for (int i = 1; i <= 5; i++) {
            factorials[i] = factorials[i - 1] * i;
        }
    }

    public static int getFactorial(int n) {
        if (n >= 0 && n <= 5) return factorials[n];
        return -1;
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("5! = " + FactorialLookup.getFactorial(5));
    }
}

