class DnsCache {
    private static String[] domains;
    private static String[] ips;

    static {
        domains = new String[]{"example.com", "dns.google", "localhost"};
        ips = new String[]{"93.184.216.34", "8.8.8.8", "127.0.0.1"};
    }

    public static String resolveIp(String domain) {
        if (domain == null) return "NOT_FOUND";
        for (int i = 0; i < domains.length; i++) {
            if (domains[i].equalsIgnoreCase(domain.trim())) {
                return ips[i];
            }
        }
        return "NOT_FOUND";
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("Resolved: " + DnsCache.resolveIp("dns.google"));
    }
}
